// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    TestToken token;
    uint256 constant PK = 1;
    address maker;

    function setUp() public {
        c = new C("", 0, address(this));
        token = new TestToken();
        maker = vm.addr(PK);
    }

    function testFuzz_property(uint256 nonce, address recipient, uint256 duration, uint256 expiration) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != maker);
        duration = bound(duration, 0, 10_000 days - 1);
        expiration = bound(expiration, block.timestamp + 1, block.timestamp + 365 days);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: false,
            isLong: false,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(PK, orderHash);

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        c.fillOrder(order, abi.encodePacked(r, s, v), floorAssetTokenIds);

        uint256 id = uint256(orderHash);

        vm.prank(maker);
        c.transferFrom(maker, recipient, id);

        assertTrue(c.ownerOf(id) == recipient);
    }
}

contract TestToken {
    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant MAKER_PK = 0xA11CE;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(address to, uint256 warpTime) public {
        // keep recipient admissible: nonzero and distinct from the sender/owner
        vm.assume(to != address(0));
        address maker = vm.addr(MAKER_PK);
        vm.assume(to != maker);
        vm.assume(to != address(this));
        bound(warpTime, 1, 1_000_000);
        vm.warp(warpTime);

        // Build a simple long put order (premium 0, strike 0) so fillOrder's token
        // transfers are no-ops accepted by SafeTransferLib (empty return = success).
        C.Order memory order;
        order.maker = maker;
        order.isCall = false;
        order.isLong = true;
        order.baseAsset = address(this); // has code, passes baseAsset check
        order.strike = 0;
        order.premium = 0;
        order.duration = 1 days;
        order.expiration = warpTime + 1 days;
        order.nonce = 0;

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(MAKER_PK, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        c.fillOrder(order, signature, new uint256[](0));

        // position minted to the caller (the test contract)
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 positionId = uint256(oppositeHash);

        // transfer the position from the caller to the fuzzed recipient `to`
        c.transferFrom(address(this), to, positionId);

        // RULE: after transferFrom(id, to), c must report `to` as the owner of id.
        assertTrue(c.ownerOf(positionId) == to);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C("", 0, address(this));
    }

    function testFuzz_property(address from, address to, address thirdParty, uint256 id) public {
        vm.assume(from != address(0) && to != address(0) && thirdParty != address(0));
        vm.assume(from != to && to != thirdParty && from != thirdParty);

        // mint token `id` to `from` by filling a trivial order signed by from is complex;
        // instead use the public mint path via fillOrder is heavy, so simulate ownership via
        // the owner recording done by fillOrder is unnecessary: use _mint indirectly through
        // fillOrder with a self-signed order using vm.sign (allowed pattern) is avoided;
        // simpler: create ownership through exercise of the NFT contract is not public.
        // Therefore we deploy nothing and instead register ownership by filling a long call order
        // with empty arrays, signed by `from`.

        // Build minimal order
        C.Order memory order;
        order.maker = from;
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(new DummyERC20());
        order.strike = 0;
        order.premium = 0;
        order.duration = 1 days;
        order.expiration = block.timestamp + 1 days;
        order.nonce = 0;

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(1, orderHash);
        bytes memory sig = abi.encodePacked(r, s, v);

        // baseAsset must have code; the maker `from` must hold baseAsset for the (zero) transfer;
        // zero-amount safeTransferFrom on DummyERC20 succeeds even without balance.
        vm.prank(from);
        c.fillOrder(order, sig, new uint256[](0));

        uint256 positionId = uint256(c.hashOppositeOrder(order));
        require(c.ownerOf(positionId) != address(0));

        // The opposite (short) position is minted to the filler (us). Transfer it from us to `to`.
        c.transferFrom(address(this), to, positionId);

        // Rule: after a transfer, the recorded owner is `to`, so `to` can transfer it onward.
        vm.prank(to);
        bool ok;
        try c.transferFrom(to, thirdParty, positionId) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "new owner must be able to transfer the token onward");
    }
}

contract DummyERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(address actor, address from, address to, uint256 id) public {
        // unminted ids and nonzero actors/recipients keep the domain wide but admissible
        vm.assume(actor != address(0));
        vm.assume(to != address(0));
        if (id < 2) id = id + 2; // keep id >= 2 but still essentially arbitrary

        // An arbitrary non-owner caller attempts to move token `id`.
        vm.prank(actor);
        bool ok;
        try c.transferFrom(from, to, id) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a caller who is not the token's owner (and not approved) can never
        // complete a transferFrom on an unminted token — the call must revert and
        // ownership must remain unminted.
        assertTrue(!ok && c.tryOwnerOfUnminted(id) == address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    FakeToken token;

    function setUp() public {
        token = new FakeToken();
        c = new C("", 0, address(this));
    }

    function testFuzz_property(address to, bool useLong) public {
        // Build a minimal long call order; maker is this test contract, which
        // supports ERC-1271 (isValidSignature below), so an empty signature verifies.
        C.Order memory order;
        order.maker = address(this);
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(token);
        order.strike = 0;
        order.premium = 0;
        order.duration = 1;
        order.expiration = block.timestamp + 100;
        order.nonce = 0;

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppHash = c.hashOppositeOrder(order);

        uint256[] memory floors = new uint256[](0);
        c.fillOrder(order, "", floors);

        uint256 id = useLong ? uint256(orderHash) : uint256(oppHash);

        // Admissible domain: id must be owned by the caller (this contract).
        // (It is, by construction, for both ids.)

        try c.transferFrom(id, to) {
            // transfer succeeded
        } catch {
            // reference reverts when to == address(0); that is fine
        }

        // General rule: after any transferFrom, ownerOf(id) succeeds and is non-zero.
        bool ok;
        try c.ownerOf(id) returns (address o) {
            ok = (o != address(0));
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }

    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }
}

contract FakeToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
